import type { EngineInterface, ModelEffort, ModelUsage, Register } from 'claude-code'

const MODELS = {
  haiku: 'claude-haiku-5-5',
  sonnet: 'claude-sonnet-5-5',
  opus: 'claude-opus-5-5',
  fable: 'claude-fable-5-1',
} as const
type Tier = keyof typeof MODELS
const RANK = Object.keys(MODELS) as Tier[] // weakest first
const EFFORTS: readonly ModelEffort[] = ['low', 'medium', 'high', 'xhigh', 'max']

// $ per 1M tokens: [input, cache write (assumed 1.25× input), cache read, output].
// ponytail: copied from the claude-api skill table (2026-10-06); update when prices move.
const PRICE: Record<Tier, readonly [number, number, number, number]> = {
  haiku: [0.1, 0.125, 0.01, 0.5],
  sonnet: [2, 2.5, 0.2, 10],
  opus: [4, 5, 0.2, 20],
  fable: [10, 12.5, 0.25, 50],
}

const RULES = `You route a coding-assistant request to a model and an effort level.
Reply with JSON only: {"model":"haiku|sonnet|opus|fable","effort":"low|medium|high|xhigh|max"}. Add "delegate":true for a long release step (deploy, OTA update, build, publish; not commit or push alone). Add "new":true when a <task> is given and the request is a separate piece of work unrelated to it (another feature or another part of the app), not a step, fix or follow-up of it.

Model = how much the work has to take in:
- haiku: one small step — chit-chat, a lookup, a typo, a rename, a one-line change.
- sonnet: work in one place or one feature — adding a feature, a visual or layout fix, a small bug, tests, explaining code.
- opus: work spanning many files, a cause that must be hunted down across the codebase, or a costly mistake.
- fable: large open-ended work — designing a system, deep research, novel algorithms, long autonomous runs.

Effort = how subtle getting it right is, chosen independently of the model:
- low: mechanical — commit, push, deploy, renames, following a clear pattern.
- medium: normal work.
- high: subtle correctness — concurrency, dates and time zones, money math, state that can be corrupted, runtime-behavior migrations (error handling, async semantics).
- xhigh / max: only very hard reasoning.

Principles:
- A costly mistake raises the floor: money, payments, auth, security, data loss → at least opus · medium.
- What makes a bug hard is not knowing where it lives, not vague wording: "prices don't match" can hide anywhere (opus · high); "buttons shift on the home page" sits in one place (sonnet · medium).
- Release chores keep the <previous> model at effort low, even when they touch risky code.
- If the <request> itself names a model or effort ("opus ile", "max effort"), use it; ignore names inside pasted code, logs or quotes.
- A short follow-up to the <previous> work ("devam", "evet", "tamam uygula", "düzelt", "go on") keeps the <previous> route.
- When no rule clearly fits, add "unsure":true and still give your best guess.`

// Prompts no person typed (notifications, schedules, peers, channels, plugins) stay unrouted.
const MACHINE: readonly string[] = ['task-notification', 'scheduled-trigger', 'peer', 'peer-send-message', 'projects-relay', 'channel', 'coordinator', 'observer', 'observer-activity', 'slack-ping', 'auto-continuation', 'plugin']

export type Route = { model: Tier; effort: ModelEffort }

// Where the router lands when nothing fits or the classifier gives no usable answer.
export const FALLBACK: Route = { model: 'sonnet', effort: 'medium' }

// Added beside a release step: the main model decides, a Haiku subagent runs it and reads the log.
export const DELEGATE_HINT = `[auto-model-detector] This is a long-running release step (deploy / OTA / build / publish). Decide the exact command, working directory and target (channel, branch, environment) yourself, then run it through the Agent tool with model "haiku": give it that exact command and cwd, tell it to change nothing else, to wait for completion, and to reply only with success or failure, the key error lines and any URL or build id. Keep the full log out of this conversation; if it fails, diagnose here.`

// Whether the classifier flagged a release step to hand to a Haiku subagent.
export const isDelegate = (text: string) => /"delegate"\s*:\s*true/.test(text)

// Whether the classifier said no rule clearly fits; the router then asks again at medium effort.
export const isUnsure = (text: string) => /"unsure"\s*:\s*true/.test(text)

// Whether the classifier rated the request a separate task, unrelated to the session's main work.
export const isNew = (text: string) => /"new"\s*:\s*true/.test(text)

// Added beside an unrelated task: a subagent with a clean context does it, so the main
// context neither pays for nor fills up with it. The full-context main model has the last word.
export const newTaskHint = (r: Route) =>
  `[auto-model-detector] This request looks like a separate task, unrelated to the earlier work in this conversation. If it takes more than a couple of steps, hand it to a subagent through the Agent tool with model "${r.model}" and effort "${r.effort}", with a self-contained brief (project path, goal, constraints, how to verify, and any conventions or decisions from this conversation that apply). For follow-ups on that task, continue the same subagent with SendMessage instead of starting a new one, and relay its result briefly. If it is a one-step change, or it actually continues the earlier work, ignore this note and do it yourself.`


type Stats = Record<string, { steps: number } & ModelUsage>

// Parses the classifier's reply; undefined when it is not a valid route.
export const parseRoute = (text: string): Route | undefined => {
  try {
    const r = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1))
    // Only the two fields: flags like "delegate" must not ride along into <previous>.
    return Object.hasOwn(MODELS, r.model) && EFFORTS.includes(r.effort) ? { model: r.model, effort: r.effort } : undefined
  } catch {
    return undefined
  }
}

// The stronger of two tiers: the session only moves up, since a model switch rewrites the cache.
export const atLeast = (a: Tier, b: Tier | undefined): Tier =>
  b && RANK.indexOf(b) > RANK.indexOf(a) ? b : a

// Long pastes usually end with the question: keep the head and the tail. The classifier's
// own tags are removed, so pasted text cannot close <request> and pose as <previous> or <task>.
export const clip = (text: string) => {
  const clean = text.replace(/<\/?(request|previous|task)>/gi, '')
  return clean.length <= 3000 ? clean : `${clean.slice(0, 1500)}\n…\n${clean.slice(-1500)}`
}

// What the user confirms before it runs, chosen in the /auto-model-detector menu (both by default).
export type Confirm = 'effort' | 'fable'
// Dialog texts: Turkish, then English underneath.
const CONFIRM_LABELS: Record<Confirm, string> = { effort: 'Yüksek effort (xhigh/max) / High effort', fable: "Fable'a geçiş / Switch to Fable" }
const COSTLY: readonly ModelEffort[] = ['xhigh', 'max']

const named = (word: string, text: string) => new RegExp(`\\b${word}\\b`, 'i').test(text)

// Asks one question; a dismissed dialog or an unknown answer is `fallback`.
const pick = async <T extends string>($: EngineInterface, question: string, header: string, options: T[], fallback: T): Promise<T> => {
  try {
    const answer = await $.ui.ask(question, { header, options })
    return options.includes(answer as T) ? (answer as T) : fallback
  } catch {
    // Say so: otherwise the user never learns why Fable or max did not come.
    $.ui.toast(`router: onay sorulamadı / could not ask → ${fallback}`)
    return fallback
  }
}

// The route the user settles on: costly choices are confirmed unless the user
// named them in the prompt or already runs on them (a follow-up never re-asks).
export const confirmRoute = async ($: EngineInterface, r: Route, text: string, confirm: readonly Confirm[], last?: Route, current?: Tier): Promise<Route> => {
  let { model, effort } = r
  if (confirm.includes('fable') && model === 'fable' && current !== 'fable' && !named('fable', text)) {
    model = await pick($, 'Router Fable seçti (Opus\'tan ~2.5× pahalı). Hangi modelle çalışsın?\nRouter picked Fable (~2.5× the price of Opus). Which model should run?', 'Model', ['fable', 'opus', 'sonnet'] as Tier[], 'opus')
  }
  if (confirm.includes('effort') && COSTLY.includes(effort) && effort !== last?.effort && !named(effort, text)) {
    effort = await pick($, `Router ${model} · ${effort} seçti. Bu effort ile mi çalışsın?\nRouter picked ${model} · ${effort}. Run at this effort?`, 'Effort', [effort, 'high', 'medium'], 'high')
  }
  return { model, effort }
}

const tierOf = (model: string) => RANK.find(t => model.includes(t))

const statsText = (stats: Stats) => {
  let total = 0
  const rows = Object.entries(stats).map(([model, s]) => {
    const p = PRICE[tierOf(model) ?? 'opus']
    const usd = (s.input_tokens * p[0] + s.cache_creation_input_tokens * p[1] + s.cache_read_input_tokens * p[2] + s.output_tokens * p[3]) / 1e6
    total += usd
    return `${model}: ${s.steps} steps · in ${s.input_tokens} · cache write ${s.cache_creation_input_tokens} · cache read ${s.cache_read_input_tokens} · out ${s.output_tokens} · ≈$${usd.toFixed(2)}`
  })
  return rows.length ? `${rows.join('\n')}\ntotal ≈$${total.toFixed(2)} (API prices, subagents included)` : 'router: no steps recorded yet'
}

const record = async ($: EngineInterface, u: ModelUsage & { model: string }) => {
  const stats = ((await $.store.get('stats')) ?? {}) as Stats
  const s = (stats[u.model] ??= { steps: 0, input_tokens: 0, output_tokens: 0, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 })
  s.steps++
  s.input_tokens += u.input_tokens
  s.output_tokens += u.output_tokens
  s.cache_read_input_tokens += u.cache_read_input_tokens
  s.cache_creation_input_tokens += u.cache_creation_input_tokens
  await $.store.set('stats', stats)
}

export const register: Register = on => {
  // ponytail: module variables reset on hot reload; move to $.state if mid-session reloads matter.
  let route: Route | undefined // this turn's route
  let handover: string | undefined // what this turn's note hands to a subagent, shown in the status line
  let last: Route | undefined // the main loop's latest route, for follow-ups
  let task: string | undefined // the prompt that opened the main work; delegated tasks never replace it
  let current: Tier | undefined // the model the main loop runs on; only moves up

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'auto-model-detector', description: 'Model router: /auto-model-detector (menu) | on | off | confirm | stats | stats reset' })
    return next(e)
  })

  // /clear starts a fresh context: the next prompt may pick any model again.
  on('session.end', ($, e, next) => {
    if (e.reason === 'clear') {
      current = last = route = undefined
      task = undefined
    }
    return next(e)
  })

  on('command.run', { command: 'auto-model-detector' }, async ($, e) => {
    let arg = e.args.trim()
    if (!arg) {
      const isOn = (await $.store.get('enabled')) !== false
      const menu = {
        toggle: isOn ? 'Kapat / Turn off' : 'Aç / Turn on',
        confirm: 'Onay ayarları / Confirmations',
        stats: 'İstatistik / Stats',
        reset: 'İstatistiği sıfırla / Reset stats',
      }
      let choice: string
      try {
        choice = await $.ui.ask(`Router ${isOn ? 'açık' : 'kapalı'}${current ? ` · oturum ${current}` : ''}. Ne yapmak istersin?\nRouter ${isOn ? 'on' : 'off'}${current ? ` · session ${current}` : ''}. What do you want to do?`, { header: 'Router', options: Object.values(menu) })
      } catch (err) {
        // Say why instead of falling back silently, and show the typed commands.
        return { text: `router: menü açılamadı / menu unavailable (${err instanceof Error ? err.message : String(err)})\nrouter ${isOn ? 'on' : 'off'} · /auto-model-detector on | off | confirm | stats | stats reset` }
      }
      arg = choice === menu.toggle ? (isOn ? 'off' : 'on') : choice === menu.confirm ? 'confirm' : choice === menu.stats ? 'stats' : choice === menu.reset ? 'stats reset' : 'status'
    }
    if (arg === 'confirm') {
      // Multi-select answers come back comma-joined; "Hiçbiri / None" (or nothing known) turns all confirmations off.
      let answer = ''
      try {
        answer = await $.ui.ask('Hangi durumlarda sana sorulsun?\nWhen should the router ask you first?', { header: 'Onay/Confirm', options: [...Object.values(CONFIRM_LABELS), 'Hiçbiri / None'], multiSelect: true })
      } catch {
        return { text: 'router: onay ayarları değişmedi / confirmations unchanged' }
      }
      const chosen = (Object.keys(CONFIRM_LABELS) as Confirm[]).filter(k => answer.includes(CONFIRM_LABELS[k]))
      await $.store.set('confirm', chosen)
      return { text: `router: onay / confirm → ${chosen.length ? chosen.map(k => CONFIRM_LABELS[k]).join(', ') : 'hiçbiri / none'}` }
    }
    if (arg === 'stats') return { text: statsText(((await $.store.get('stats')) ?? {}) as Stats) }
    if (arg === 'stats reset') {
      await $.store.delete('stats')
      return { text: 'router: stats cleared' }
    }
    if (arg === 'on' || arg === 'off') await $.store.set('enabled', arg === 'on')
    const isOn = (await $.store.get('enabled')) !== false
    if (!isOn) $.ui.status(undefined)
    return { text: `router: ${isOn ? 'on' : 'off'}${current ? ` · session on ${current}` : ''}` }
  })

  on('prompt.submit', async ($, e, next) => {
    // Typed into a running turn: that turn keeps its route.
    if (e.turnId) return next(e)
    route = handover = undefined
    if (MACHINE.includes(e.origin?.kind) || e.text.trimStart().startsWith('/')) return next(e)
    if ((await $.store.get('enabled')) === false) return next(e)
    if (!(await $.session.model()).includes('haiku')) return next(e)

    const previous = last ? `<previous>${JSON.stringify(last)}</previous>\n` : ''
    const taskTag = task ? `<task>${task}</task>\n` : ''
    // Low effort first (~1 s); only a request it is unsure of, or cannot answer, is asked again at
    // medium effort; if that is unsure too, the route is sonnet · medium.
    const prompt = `${previous}${taskTag}<request>${clip(e.text)}</request>`
    let text = ''
    for (const effort of ['low', 'medium'] as const) {
      const r = await $.model.complete({
        model: 'haiku',
        system: RULES,
        prompt,
        maxTokens: effort === 'low' ? 256 : 1024, // room for thinking plus the JSON with its flags
        effort,
        timeoutMs: effort === 'low' ? 10000 : 15000,
      })
      $.ui.log(`router (${effort}): ${r.isAnswered ? r.text.trim() : `no answer (${r.reason})`}`, { to: 'debug' })
      if (r.isAnswered && parseRoute(r.text) && !isUnsure(r.text)) {
        text = r.text
        break
      }
    }
    route = parseRoute(text) ?? FALLBACK
    // ponytail: the first 300 characters of the opening prompt; summarize the main work if that proves too thin.
    task ??= clip(e.text).slice(0, 300)
    const confirm = ((await $.store.get('confirm')) ?? ['effort', 'fable']) as Confirm[]
    if (route) route = await confirmRoute($, route, e.text, confirm, last, current)
    last = route ?? last
    // An unrelated task goes to a subagent at its own route; the main loop stays where it is and
    // only hands it over, and <previous> keeps the main route so "devam" never lifts it.
    if (route && current && isNew(text) && !isDelegate(text)) {
      const handed = route
      route = last = { model: current, effort: 'low' }
      handover = `subagent ${handed.model} · ${handed.effort}`
      return next({ ...e, context: [...(e.context ?? []), newTaskHint(handed)] })
    }
    // A long release step: the main model decides, a Haiku subagent runs it and keeps the log out.
    if (route && isDelegate(text)) {
      handover = 'subagent haiku (deploy)'
      return next({ ...e, context: [...(e.context ?? []), DELEGATE_HINT] })
    }
    return next(e)
  }).catch(($, e, next) => {
    // The classifier call itself threw: same landing as an unusable answer.
    route ??= FALLBACK
    return next(e)
  })

  // A general-purpose subagent runs on the session's routed model, capped at opus.
  // ponytail: typed subagents (Explore, Plan...) keep their own model; route them too if needed.
  on('agent.spawn', async ($, e, next) => {
    if (!current || e.model || e.subagentType !== 'general-purpose' || !e.parentModel.includes('haiku')) return next(e)
    return next({ ...e, model: MODELS[RANK.indexOf(current) > RANK.indexOf('opus') ? 'opus' : current] })
  }).catch(($, e, next) => next(e))

  // Main loop only, and only while the session itself is on Haiku: pick another
  // model in the app and the router steps aside. Every step's usage is recorded.
  on('turn.step', async function* ($, e, next) {
    let sent = e
    if (!e.agentId && e.model.includes('haiku') && (route || current)) {
      const tier = atLeast(route?.model ?? 'haiku', current)
      if (tier !== current) {
        // The first step on a stronger model writes the whole context to its cache once.
        if (current) {
          const { context } = await $.session.usage()
          $.ui.toast(`router: ${current} → ${tier} (cache write ≈$${(((context.tokens ?? 0) * PRICE[tier][1]) / 1e6).toFixed(2)})`)
        }
        current = tier
      }
      sent = { ...e, model: MODELS[tier], effort: route?.effort ?? e.effort }
      $.ui.status(`router: ${tier} · ${sent.effort ?? 'default'}${handover ? ` → ${handover}` : ''}`)
    } else if (!e.agentId) {
      $.ui.status(undefined)
    }

    const result = yield* next(sent)
    if (result.usage) await record($, result.usage)
    return result
  })
}

